package com.bare.tasks.ui; import android.os.Bundle; import android.view.ViewGroup; import android.widget.*; import androidx.annotation.Nullable; import com.bare.ReferenceActivityBoundary; import com.bare.tasks.PreconditionsActivity; public class TaskActivity extends ReferenceActivityBoundary{@Override protected void onCreate(@Nullable Bundle s){super.onCreate(s);LinearLayout x=(LinearLayout)((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);x.removeViewAt(1);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(32,24,32,24);TextView t=new TextView(this);t.setText("Task execution");b.addView(t);Button p=new Button(this);p.setText("Check preconditions");p.setOnClickListener(v->startActivity(new android.content.Intent(this,PreconditionsActivity.class)));b.addView(p);Button c=new Button(this);c.setText("Cancel");c.setOnClickListener(v->finish());b.addView(c);x.addView(b,new LinearLayout.LayoutParams(-1,0,1));}}